  admin: ReturnType<typeof getAdminCodec> & SelfFetchFunctions<AdminArgs, Admin>;
  lpPosition: ReturnType<typeof getLpPositionCodec> &
    SelfFetchFunctions<LpPositionArgs, LpPosition>;
  marketThree: ReturnType<typeof getMarketThreeCodec> &
    SelfFetchFunctions<MarketThreeArgs, MarketThree>;
