export type ExponentClmmPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function exponentClmmProgram() {
  return <T extends ExponentClmmPluginRequirements>(
    client: T
  ): ExtendedClient<T, { exponentClmm: ExponentClmmPlugin }> => {
    return extendClient(client, {
      exponentClmm: <ExponentClmmPlugin>{
        accounts: {
          admin: addSelfFetchFunctions(client, getAdminCodec()),
          lpPosition: addSelfFetchFunctions(client, getLpPositionCodec()),
          marketThree: addSelfFetchFunctions(client, getMarketThreeCodec()),
          vault: addSelfFetchFunctions(client, getVaultCodec()),
        },
        instructions: {
          addFarm: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAddFarmInstruction({ ...input, feePayer: input.feePayer ?? client.payer })
            ),
          addLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getAddLiquidityInstruction(input)),
          addMarketEmission: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAddMarketEmissionInstruction({
                ...input,
                feePayer: input.feePayer ?? client.payer,
              })
            ),
          buyPt: (input) => addSelfPlanAndSendFunctions(client, getBuyPtInstruction(input)),
          buyYt: (input) => addSelfPlanAndSendFunctions(client, getBuyYtInstruction(input)),
          claimFarmEmission: (input) =>
            addSelfPlanAndSendFunctions(client, getClaimFarmEmissionInstruction(input)),
          depositLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getDepositLiquidityInstruction(input)),
          initializeMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeMarketInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          marketAccrueEmission: (input) =>
            addSelfPlanAndSendFunctions(client, getMarketAccrueEmissionInstruction(input)),
          marketCollectEmission: (input) =>
            addSelfPlanAndSendFunctions(client, getMarketCollectEmissionInstruction(input)),
          modifyFarm: (input) =>
            addSelfPlanAndSendFunctions(client, getModifyFarmInstruction(input)),
          modifyMarketSetting: (input) =>
            addSelfPlanAndSendFunctions(client, getModifyMarketSettingInstruction(input)),
          sellPt: (input) => addSelfPlanAndSendFunctions(client, getSellPtInstruction(input)),
          sellYt: (input) => addSelfPlanAndSendFunctions(client, getSellYtInstruction(input)),
          tradePt: (input) => addSelfPlanAndSendFunctions(client, getTradePtInstruction(input)),
          tradePtExactOut: (input) =>
            addSelfPlanAndSendFunctions(client, getTradePtExactOutInstruction(input)),
          withdrawLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawLiquidityInstruction(input)),
          wrapperBuyYt: (input) =>
            addSelfPlanAndSendFunctions(client, getWrapperBuyYtInstruction(input)),
          wrapperProvideLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getWrapperProvideLiquidityInstruction(input)),
          wrapperProvideLiquidityBase: (input) =>
            addSelfPlanAndSendFunctions(client, getWrapperProvideLiquidityBaseInstruction(input)),
          wrapperProvideLiquidityClassic: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWrapperProvideLiquidityClassicInstruction(input)
            ),
          wrapperSellYt: (input) =>
            addSelfPlanAndSendFunctions(client, getWrapperSellYtInstruction(input)),
          wrapperWithdrawLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getWrapperWithdrawLiquidityInstruction(input)),
          wrapperWithdrawLiquidityClassic: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWrapperWithdrawLiquidityClassicInstruction(input)
            ),
        },
        identifyAccount: identifyExponentClmmAccount,
        identifyInstruction: identifyExponentClmmInstruction,
        parseInstruction: parseExponentClmmInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
